-- SOMENTE LEITURA. Execute manualmente no banco real e devolva o resultado.
select current_database() banco, current_setting('server_version') versao_postgres;
select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name='ro_passagem_solicitacoes' and column_name in('aprovador_id','aprovacao_status','aprovado_em','reprovado_em','motivo_reprovacao_aprovador') order by ordinal_position;
select p.proname,pg_get_function_identity_arguments(p.oid) argumentos,p.prosecdef security_definer,has_function_privilege('anon',p.oid,'EXECUTE') anon_executa,has_function_privilege('authenticated',p.oid,'EXECUTE') autenticado_executa from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('ro_is_denise','ro_is_approval_candidate','ro_listar_aprovadores','ro_criar_solicitacao_com_aprovador','ro_aprovar_solicitacao','ro_reprovar_solicitacao','ro_atualizar_valor_passagem') order by p.proname;
select policyname,cmd,roles,qual,with_check from pg_policies where schemaname='public' and tablename in('ro_passagem_solicitacoes','ro_passagem_custos','ro_passagem_anexos') order by tablename,policyname;
select t.tgname,c.relname tabela,pg_get_triggerdef(t.oid) definicao from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and t.tgname in('ro_bloquear_operacao_sem_aprovacao','ro_proteger_campos_aprovacao','ro_proteger_valor_passagem','ro_proteger_complemento_denise') order by t.tgname;
select u.id,u.email,p.full_name,array_remove(array_agg(r.role::text),null) papeis,public.ro_is_approval_candidate(u.id) candidato,public.ro_is_denise(u.id) denise from auth.users u left join public.users_profiles p on p.id=u.id left join public.user_roles r on r.user_id=u.id where lower(coalesce(u.email,''))='denise.pires@tanksbr.com.br' or lower(btrim(coalesce(p.full_name,''))) in('higor cardoso','flávio sturion','flavio sturion') or r.role::text='coordenador' group by u.id,u.email,p.full_name order by p.full_name nulls last;
